$progress=CommunityNetwork::progress($ledger,$entry['id']);
?>
<section class="tool-card"><h2>Supply order</h2><p><strong>Item:</strong> <?= escape($entry['item']??'See organizer instructions') ?></p>
<?php if($progress['target']): ?><p><strong>Requested:</strong> <?= number_format($progress['target']) ?> units · <strong>Verified:</strong> <?= number_format($progress['verified']) ?> · <strong>Reserved or awaiting review:</strong> <?= number_format($progress['held']) ?> · <strong>Available:</strong> <?= number_format($progress['available']) ?></p><progress max="<?= $progress['target'] ?>" value="<?= min($progress['target'],$progress['verified']) ?>" aria-label="Verified delivery progress"><?= $progress['verified'] ?> of <?= $progress['target'] ?></progress><p><strong>Reward:</strong> <?= escape($entry['reward']??'0') ?> ISK per unit. <?= escape($entry['terms']??'') ?></p><?php else: ?><p>The organizer has not set a quantity target. Confirm the request directly. Historical delivery reviews count as records, not verified item quantities.</p><?php endif; ?>
