$open=$entry['status']==='published' && ($entry['when']==='' || $entry['when']>gmdate('Y-m-d\TH:i'));
$active=[];
if($viewer)$active=array_filter($ledger['claims'],fn($c)=>$c['entry']===$entry['id'] && $c['actor']===(int)$viewer['character_id'] && ($c['status']==='pending' || ($c['status']==='reserved' && $c['expires']>time())));
?>
<?php if(!$open): ?><p>This job is closed to new reservations. Existing deliveries can still be reviewed.</p><?php elseif(!$viewer): ?><p>Sign in through the main login to reserve a delivery quantity.</p><?php elseif(!$active && $progress['target'] && $progress['available']): ?><form method="post" action="/community/delivery.php"><input type="hidden" name="csrf" value="<?= escape(eve_csrf()) ?>"><input type="hidden" name="revision" value="<?= (int)$ledger['revision'] ?>"><input type="hidden" name="action" value="reserve"><input type="hidden" name="id" value="<?= escape($entry['id']) ?>"><label>Units you will deliver<input type="number" name="quantity" min="1" max="<?= $progress['available'] ?>" step="1" required></label><button class="primary-button">Reserve this quantity</button><p class="note">Expires after 48 hours or at the job deadline, whichever is earlier.</p></form><?php elseif($progress['target'] && !$progress['available']): ?><p>The target is filled or reserved. Check other posted jobs.</p><?php elseif($viewer && !$progress['target'] && !$active): ?><form method="post" action="/community/delivery.php"><input type="hidden" name="csrf" value="<?= escape(eve_csrf()) ?>"><input type="hidden" name="revision" value="<?= (int)$ledger['revision'] ?>"><input type="hidden" name="action" value="submit"><input type="hidden" name="id" value="<?= escape($entry['id']) ?>"><label>Private delivery evidence<textarea name="evidence" required maxlength="3000" placeholder="Contract ID, quantity, EVE time and recipient."></textarea></label><button class="secondary-button">Submit for review</button></form><?php endif; ?>
